async function runAgent({ task, callModel, tools, maxTurns = 20 }) {
  const messages = [{ role: "user", content: task }];
  const seen = new Map();
  // key ที่ไม่ขึ้นกับลำดับ key ของ input
  const canonical = (v) =>
    JSON.stringify(v, (k, x) =>
      x && typeof x === "object" && !Array.isArray(x)
        ? Object.fromEntries(Object.entries(x).sort(([a], [b]) => (a < b ? -1 : 1)))
        : x);
  for (let turn = 0; turn < maxTurns; turn++) {
    const res = await callModel(messages);
    messages.push({ role: "assistant", content: res.content });
    if (res.stop_reason === "end_turn") return { status: "done", res };
    if (res.stop_reason !== "tool_use")
      return { status: "stopped", reason: res.stop_reason };
    const results = [];
    let repeated = null;
    for (const call of res.content.filter((b) => b.type === "tool_use")) {
      const key = call.name + canonical(call.input);
      const count = (seen.get(key) || 0) + 1;
      seen.set(key, count);
      if (count >= 3) {
        repeated = repeated || call;
        results.push({
          type: "tool_result",
          tool_use_id: call.id,
          content: "Not executed: repeated call",
          is_error: true,
        });
        continue;
      }
      try {
        const output = await tools[call.name](call.input);
        results.push({
          type: "tool_result",
          tool_use_id: call.id,
          content: typeof output === "string" ? output : JSON.stringify(output) ?? "",
        });
      } catch (err) {
        results.push({
          type: "tool_result",
          tool_use_id: call.id,
          content: "Tool failed: " + (err instanceof Error ? err.message : String(err)),
          is_error: true,
        });
      }
    }
    messages.push({ role: "user", content: results });
    if (repeated) return { status: "stopped", reason: "repeated_call", call: repeated };
  }
  return { status: "stopped", reason: "max_turns" };
}
